'use strict';
// Offline UI prototype only. No authentication, backend, network game, or persistence.
const app=document.getElementById('app');
const suits=[['aurora','오로라','○','#92C7B0'],['ember','여명','△','#D8A27D'],['tide','물결','◇','#83B5D6'],['moss','이끼','□','#B6C77B'],['dusk','황혼','☆','#B6A2D2']];
const games=[['별길 탐험','STAR TRAILS','○ ◇ ☆','2명 · 카드 배치','첫 번째 구현'],['빛의 공방','LIGHT WORKSHOP','◇ ◇','2–4명 · 자원과 제작','다음 단계'],['밤의 의회','NIGHT COUNCIL','▥ ◇','4–6명 목표 · 역할 선택','확장 설계'],['황혼의 신호','DUSK SIGNAL','⌁ ◇','4–7명 목표 · 숨은 진영','확장 설계'],['넘버가든','NUMBER GARDEN','▤ ▥','2–4명 목표 · 타일 배열','확장 설계']];
const hands=[[0,'8'],[1,'7'],[2,'9'],[3,'3'],[3,'6'],[4,'9'],[3,'+'],[4,'+']];
let screen=['home','lobby','room','game','result'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
let selected=0;let ready=true;let toastTimer;
const btn=(text,to,klass='')=>`<button class="btn ${klass}" data-screen="${to}">${text}</button>`;
const action=(text,act,klass='')=>`<button class="btn ${klass}" data-action="${act}">${text}</button>`;
const header=()=>`<header class="topbar"><button class="brand" data-screen="home"><span class="brandmark">▦</span>모여테이블<small>TABLE / TOGETHER</small></button><nav class="nav"><button data-screen="lobby" class="${screen==='lobby'?'active':''}">게임 둘러보기</button><button data-screen="room">내 테이블</button><button data-action="help">이용 방법</button></nav><span class="demo-tag">UI DEMO · 서버 미연결</span><div class="avatar">나</div></header>`;
const footer=()=>`<footer class="bottom-note"><span>가칭 · 모여테이블 / 설치 없이, 우리끼리 한 판.</span><span>이 화면은 개발용 시안입니다. 실제 회원·접속자·플레이 결과가 아닙니다.</span></footer>`;
function gameCards(lobby=false){return `<div class="game-grid ${lobby?'lobby-grid':''}">${games.map((g,i)=>`<article class="game-card"><div class="game-art art-${i}"><span class="abstract">${g[2]}</span><span class="art-name">${g[1]}</span></div><div class="card-body"><span class="badge ${i?'later':''}">${g[4]}</span><h3>${g[0]}</h3><p>${g[3]}</p>${lobby?`<div style="margin-top:14px">${i?action('준비 중','later','small ghost'):btn('테이블 열기 →','room','small')}</div>`:''}</div></article>`).join('')}</div>`;}
function home(){return `<section class="hero"><div><div class="eyebrow">A SMALL PLACE FOR YOUR PEOPLE</div><h1>게임은 바뀌어도,<br><em>우리의 테이블은</em><br>계속 이어지니까.</h1><p>친구에게 링크 하나 보내세요.<br>같은 테이블에서 고르고, 즐기고, 다시 한 판.</p><div class="actions">${btn('우리 테이블 만들기 ↗','room')}${btn('게임 둘러보기','lobby','secondary')}</div><div class="micro">설치 없이 브라우저에서 · 친구 초대 중심 · 무료 이용</div></div><div class="hero-scene"><div class="scene-orbit"></div><div class="scene-orbit two"></div><div class="hero-card one"><div class="num">3</div><div class="sig">○</div><div class="label">AURORA</div></div><div class="hero-card two"><div class="num">7</div><div class="sig">◇</div><div class="label">TIDE</div></div><div class="hero-card three"><div class="num">9</div><div class="sig">☆</div><div class="label">DUSK</div></div><div class="scene-caption"><span>별길 탐험 / 첫 번째 테이블</span><div class="chips"><span class="chip"></span><span class="chip"></span><span class="chip"></span></div></div></div></section><div class="section-head"><div><div class="eyebrow">OUR GAME COLLECTION</div><h2>오늘은 어떤 한 판?</h2></div><p>첫 게임을 완성하고, 하나씩 넓혀갑니다.</p></div>${gameCards()}${footer()}`;}
function lobby(){return `<div class="page-header"><div><div class="eyebrow">YOUR CORNER OF THE CAFE</div><h1>오늘도, 같은 테이블.</h1><p>친구와 만나고 새 게임을 고르는 공간</p></div>${btn('+ 테이블 만들기','room')}</div><div class="layout"><aside class="sidepanel"><h3>내 공간</h3><div class="sideitem active">전체 게임 <span>5</span></div><div class="sideitem">첫 구현 대상 <span>1</span></div><div class="sideitem">후속 게임 <span>4</span></div><div class="sideitem">초대받은 테이블 <span>예시</span></div><p class="micro">홈페이지는 공개입니다.<br>우리 테이블은 초대받은<br>멤버에게만 보입니다.</p></aside><section><div class="table-banner"><div><h3>금요일의 작은 테이블</h3><p>별길 탐험 · 2 / 2명 · 대기실 예시</p></div>${btn('테이블 입장 →','room','small')}</div><div class="section-head"><div><h2>게임 선반</h2><p>준비 중인 게임은 시작할 수 없습니다.</p></div></div>${gameCards(true)}</section></div>${footer()}`;}
function room(){return `<div class="page-header"><div><div class="eyebrow">TABLE 01 / PRIVATE</div><h1>금요일의 작은 테이블</h1><p>한 판이 끝나도 같은 테이블에서 이어서 즐겨요.</p></div>${action('초대 링크 복사','invite','secondary')}</div><div class="room-grid"><div class="room-board"><div class="seat top"><div class="avatar" style="background:#d4b391">친구</div><div><strong>플레이어 B</strong><small>준비 완료</small></div></div><div class="table-medallion"><div class="sig">○ ◇ ☆</div><strong>별길 탐험</strong><small>2 PLAYERS / ONE ROUND</small></div><div class="seat bottom"><div class="avatar">나</div><div><strong>플레이어 A · 방장</strong><small>${ready?'준비 완료':'준비 전'}</small></div></div></div><div class="panel"><h3>함께할 게임</h3><div class="field"><label>선택한 게임</label><div class="fieldbox">별길 탐험 <span class="muted">/ 첫 번째 구현</span></div></div><div class="field"><label>플레이 방식</label><div class="fieldbox">기본 규칙 · 단판 · 목표 확장 없음</div></div><div class="keyvals"><span class="muted">테이블 공개 범위</span><span>초대된 멤버만</span><span class="muted">참가자</span><span>2 / 2명</span><span class="muted">접속 끊김</span><span>180초 복귀 유예</span><span class="muted">동점 처리</span><span>공동 승리</span></div><button class="btn full" data-screen="game" ${!ready?'disabled':''}>모두 준비됐어요. 시작하기 →</button><div class="actions" style="margin-top:12px">${action(ready?'준비 해제':'준비하기','ready','small secondary')}${action('규칙 확인','help','small secondary')}</div><p class="room-note">게임을 바꾸거나 멤버가 바뀌면 준비 상태를 다시 확인합니다. 이 화면의 참가자는 시안용 예시입니다.</p></div></div>${footer()}`;}
const myLanes=[['+',2,6],[3,5],['+',4,7],[],[2,8]];const opLanes=[['+',3,7],[2,6],[],['+',5],[4]];
function lanes(arr,mine){return `<div class="lanes">${arr.map((a,i)=>`<div class="lane ${mine&&selected>=0&&hands[selected][0]===i?'suitable':''}" style="--suit:${suits[i][3]}" ${mine?'data-action="place"':''}><div class="lane-top"><span class="suitmark">${suits[i][2]}</span><span>${suits[i][1]}</span></div><div class="lane-cards">${a.length?a.map(v=>`<span class="mini-card">${v}</span>`).join(''):'<span class="empty-label">시작 전</span>'}</div><small>${a.length?`${a.length}장 · 마지막 ${a.at(-1)}`:'비어 있는 경로 0점'}</small></div>`).join('')}</div>`;}
function game(){return `<div class="play-header"><div><h1>별길 탐험</h1><p>금요일의 작은 테이블 · 단판 · 기본 규칙</p></div><div class="actions"><div class="status-pill"><span class="dot"></span>내 차례 · 카드 놓기</div>${action('규칙','help','small secondary')}${btn('결과 예시','result','small secondary')}</div></div><div class="play-layout"><div><div class="board"><div class="player-row"><div class="player-tag"><div class="avatar" style="background:#d4b391">B</div><strong>플레이어 B</strong><span class="smallmuted">손패 8장 · 비공개</span></div><span class="score-label">진행 점수<b>−78</b></span></div>${lanes(opLanes,false)}<div class="discard-zone">${suits.map((s,i)=>`<div class="discard" style="--suit:${s[3]}"><span class="mini-card">${[4,4,5,4,5][i]}</span><span>버림 더미</span></div>`).join('')}</div><div class="player-row"><div class="player-tag"><div class="avatar">A</div><strong>나의 관측 기록</strong><span class="smallmuted">색과 기호를 맞추세요</span></div><span class="score-label">진행 점수<b>−64</b></span></div>${lanes(myLanes,true)}</div><section class="hand-panel"><div class="hand-header"><strong>내 손패 · 8장</strong><span>① 카드 선택 → ② 경로에 놓기 → ③ 한 장 뽑기</span></div><div class="hand">${hands.map(([i,n],j)=>`<button class="playcard ${selected===j?'selected':''}" data-card="${j}" style="--suit:${suits[i][3]}" aria-label="${suits[i][1]} ${n==='+'?'지원':n} 카드"><span class="value">${n}</span><span class="symbol">${suits[i][2]}</span><span class="suitname">${suits[i][1]} ${n==='+'?'지원':'관측'}</span><span class="corner">${n}</span></button>`).join('')}</div><div class="actionbar"><div class="hint">${selected>=0?`${suits[hands[selected][0]][1]} ${hands[selected][1]==='+'?'지원':hands[selected][1]} 선택됨 · 같은 기호 경로를 누르세요.`:'먼저 카드 한 장을 선택하세요.'}<br>이 화면은 조작 흐름 시안이며 서버에 행동을 전송하지 않습니다.</div><div class="actions">${action('선택 카드 놓기','place')}${action('버리기','discard','secondary')}</div></div></section><div class="screen-label">VIEW 04 / DESKTOP & MOBILE · 선택·버튼 반응만 시연 · 실제 온라인 플레이 미구현</div></div><aside class="game-aside"><div class="panel logpanel"><div class="eyebrow">DRAW PILE</div><div class="deck-block"><div class="star">✧</div><b>21</b><span>남은 카드 · 덱 순서는 비공개</span></div><h3 style="font-size:14px">테이블 기록</h3><div class="log-item">B가 여명 6을 놓았습니다.<small>공개 행동 예시</small></div><div class="log-item">B가 덱에서 한 장 뽑았습니다.<small>뽑은 카드의 정체는 숨깁니다.</small></div><div class="log-item">나의 차례입니다.<small>경로에 놓거나 한 장 버리세요.</small></div><div class="notice">카드는 오름차순으로.<br>지원 카드는 숫자보다 먼저.<br>덱 마지막 장을 뽑으면 종료.</div></div></aside></div>`;}
function result(){return `<div class="result-wrap"><div class="result-hero"><div class="eyebrow">ROUND COMPLETE / EXAMPLE</div><div class="wreath">✧</div><h1>좋은 한 판이었어요.</h1><p>결과 예시 · 점수는 산식까지 함께 확인합니다.</p></div><div class="scores"><div class="scorebox winner"><div><span>플레이어 A · 승리</span><small>5개 경로 합산</small></div><b>18 <span>점</span></b></div><div class="scorebox"><div><span>플레이어 B</span><small>비교용 예시 점수</small></div><b style="color:#b8c7c3">−8 <span>점</span></b></div></div><div class="panel"><h3>내 점수, 어떻게 계산됐나요?</h3><table class="result-table"><thead><tr><th>경로</th><th>숫자 합계</th><th>배수</th><th>보너스</th><th>계산</th><th>점수</th></tr></thead><tbody>${[['○ 오로라','23','×1','0','(23−20)×1','3'],['△ 여명','0','—','0','시작하지 않음','0'],['◇ 물결','0','×2','0','(0−20)×2','−40'],['□ 이끼','15','×2','0','(15−20)×2','−10'],['☆ 황혼','35','×3','20','(35−20)×3+20','65']].map(r=>`<tr>${r.map((c,i)=>`<td class="${i===4?'formula':''}">${c}</td>`).join('')}</tr>`).join('')}<tr class="total"><td colspan="5">총점</td><td>18</td></tr></tbody></table></div><div class="center-actions">${btn('같은 멤버로 다시 하기','room')}${btn('다른 게임 고르기','lobby','secondary')}</div><div class="inline-note">재경기는 새 세션과 새 덱으로 시작합니다.<br>위 결과는 점수 계산을 설명하는 예시로, 이전 시안 화면을 진행한 결과가 아닙니다.</div></div>${footer()}`;}
function render(){app.innerHTML=`<main class="shell">${header()}<div class="screen-fade">${({home,lobby,room,game,result}[screen]??home)()}</div></main>`;}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3700);}
function help(){const o=document.createElement('div');o.className='help-overlay';o.innerHTML=`<section class="help-dialog" role="dialog" aria-modal="true" aria-label="기본 규칙"><div class="eyebrow">STAR TRAILS / RULES 1.0</div><h2>한 장 놓고, 한 장 뽑기.</h2><p>같은 색과 기호의 경로에 숫자를 오름차순으로 놓습니다. 지원 카드는 숫자보다 먼저 놓습니다. 놓지 않을 카드는 버릴 수 있지만, 방금 버린 카드를 바로 다시 가져올 수는 없습니다.</p><code>(숫자 합계 − 20) × (지원 수 + 1)<br>+ 8장 이상 경로 보너스 20</code><p>시작하지 않은 경로는 0점. 덱 마지막 장을 뽑으면 즉시 종료합니다. 동점이면 공동 승리입니다.</p>${action('닫기','close','full')}</section>`;app.appendChild(o);o.querySelector('button').focus();}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-screen]');if(nav){screen=nav.dataset.screen;location.hash=screen;render();window.scrollTo(0,0);return;}const card=e.target.closest('[data-card]');if(card){selected=Number(card.dataset.card);render();return;}const x=e.target.closest('[data-action]');if(!x)return;switch(x.dataset.action){case'help':help();break;case'close':document.querySelector('.help-overlay')?.remove();break;case'invite':toast('초대 링크 발급·복사는 서버 구현 단계에서 연결합니다.');break;case'later':toast('이 게임은 확장 설계 단계입니다. 먼저 별길 탐험을 구현합니다.');break;case'ready':ready=!ready;render();break;case'place':toast('배치 입력 시연입니다. 실제 게임에서는 서버가 규칙을 검증한 뒤 반영합니다.');break;case'discard':toast('버리기 입력 시연입니다. 실제 게임에서는 승인 후 뽑기 단계로 이동합니다.');break;}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['home','lobby','room','game','result'].includes(next)&&next!==screen){screen=next;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('.help-overlay')?.remove();});
render();
